// Function to sum money amounts in cents
function sumMoney(list) {
    // Handle empty array
    if (list.length === 0) {
        return 0;
    }

    // Validate that all items are integers
    for (const amount of list) {
        if (!Number.isInteger(amount)) {
            throw new Error(`All items must be integers, got: ${amount}`);
        }
    }

    // Sum all amounts
    return list.reduce((sum, amount) => sum + amount, 0);
}

// Function to compare two money values
function compareMoney(a, b) {
    // Validate that both arguments are integers
    if (!Number.isInteger(a)) {
        throw new Error(`First argument must be an integer, got: ${a}`);
    }
    if (!Number.isInteger(b)) {
        throw new Error(`Second argument must be an integer, got: ${b}`);
    }

    // Compare and return -1, 0, or 1
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
}

module.exports = {
    parseMoney,
    formatMoney,
    addMoney,
    subtractMoney,
    multiplyMoney,
    splitMoney,
    allocateMoney,
    taxMoney,
    convertMoney,
    sumMoney,
    compareMoney
};

const { sumMoney, compareMoney } = require('./r8_money.js');

// Test sumMoney
console.log("Testing sumMoney:");
console.log("sumMoney([]):", sumMoney([])); // Should be 0
console.log("sumMoney([100, 200]):", sumMoney([100, 200])); // Should be 300
console.log("sumMoney([50, -25, 75]):", sumMoney([50, -25, 75])); // Should be 100

// Test compareMoney
console.log("\nTesting compareMoney:");
console.log("compareMoney(100, 200):", compareMoney(100, 200)); // Should be -1
console.log("compareMoney(200, 100):", compareMoney(200, 100)); // Should be 1
console.log("compareMoney(100, 100):", compareMoney(100, 100)); // Should be 0

// Test error handling for sumMoney
try {
    sumMoney([100, 200.5]);
} catch (e) {
    console.log("sumMoney error handling works:", e.message);
}

// Test error handling for compareMoney
try {
    compareMoney(100, 200.5);
} catch (e) {
    console.log("compareMoney error handling works:", e.message);
}

